import{_ as r,C as a,c as o,o as s,a3 as t,G as i}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Manufacturing settings","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/get-started/manufacturing-settings.md","filePath":"master/supply-chain/manufacturing/get-started/manufacturing-settings.md","lastUpdated":1793074831000}'),d={name:"master/supply-chain/manufacturing/get-started/manufacturing-settings.md"};function h(u,e,c,g,l,p){const n=a("ImagePopup");return s(),o("div",null,[e[0]||(e[0]=t('<h1 id="manufacturing-settings" tabindex="-1">Manufacturing settings <a class="header-anchor" href="#manufacturing-settings" aria-label="Permalink to &quot;Manufacturing settings&quot;">​</a></h1><p>The settings page decides which parts of Manufacturing you see. By default you can make products with a bill of materials and a manufacturing order. Two switches add work centers, work orders and the order in which steps run.</p><blockquote><p><strong>In simple words:</strong> Switch on <strong>Work Orders</strong> to split a build into steps. Switch on <strong>Work Order Dependencies</strong> to make steps wait for each other.</p></blockquote><h2 id="open-the-settings" tabindex="-1">Open the settings <a class="header-anchor" href="#open-the-settings" aria-label="Permalink to &quot;Open the settings&quot;">​</a></h2><p>You can reach the same page in two ways:</p><ul><li><code>Manufacturing → Settings → Manage Operations</code></li><li><code>Settings → Settings → Manufacturing</code></li></ul>',6)),i(n,{src:"/images1/manufacturing/set_manage_operations.png",alt:"Manage Operations page with Work Orders and Work Order Dependencies both on, crop to the two toggles and Save Changes"}),e[1]||(e[1]=t('<h2 id="manage-operations" tabindex="-1">Manage Operations <a class="header-anchor" href="#manage-operations" aria-label="Permalink to &quot;Manage Operations&quot;">​</a></h2><ul><li><strong><em>Work Orders:</em></strong> Turn on to run operations at work centers. The help text reads &quot;Execute operations at designated work centers.&quot; A <strong>Configure work centers</strong> link appears next to it.</li><li><strong><em>Work Order Dependencies:</em></strong> Turn on to set the order in which work orders run. The help text reads &quot;Set the sequence in which work orders should be processed.&quot; The order follows the sequence of the operations on the bill of materials.</li></ul><p>Click <strong>Save Changes</strong> after you change a toggle.</p><h2 id="what-each-setting-turns-on" tabindex="-1">What each setting turns on <a class="header-anchor" href="#what-each-setting-turns-on" aria-label="Permalink to &quot;What each setting turns on&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Shows after you turn it on</th></tr></thead><tbody><tr><td><strong>Work Orders</strong></td><td><code>Manufacturing → Operations → Work Orders</code>, <code>Manufacturing → Configurations → Work Centers</code> and <strong>Operations</strong>, the <strong>Work Orders</strong> tab on a manufacturing order, the <strong>Operations</strong> tab on a bill of materials</td></tr><tr><td><strong>Work Order Dependencies</strong></td><td>Step ordering of work orders, shown on the <strong>Blocked By</strong> tab of a work order</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Turning on <strong>Work Order Dependencies</strong> also turns on <strong>Work Orders</strong>. Turning off <strong>Work Orders</strong> turns off <strong>Work Order Dependencies</strong> too.</p></div><h2 id="turning-dependencies-on-step-by-step" tabindex="-1">Turning dependencies on, step by step <a class="header-anchor" href="#turning-dependencies-on-step-by-step" aria-label="Permalink to &quot;Turning dependencies on, step by step&quot;">​</a></h2><ol><li>Go to <code>Manufacturing → Settings → Manage Operations</code>.</li><li>Turn on <strong>Work Orders</strong>.</li><li>Turn on <strong>Work Order Dependencies</strong>.</li><li>Click <strong>Save Changes</strong>.</li></ol><p>Each work order then waits for the one before it. See <a href="./../advanced-configuration/work-order-dependencies.html">Work order dependencies</a>.</p><h2 id="warehouse-steps" tabindex="-1">Warehouse steps <a class="header-anchor" href="#warehouse-steps" aria-label="Permalink to &quot;Warehouse steps&quot;">​</a></h2><p>The warehouse <strong>Manufacturing</strong> choice (one, two or three steps) lives in Inventory, not here. It needs <strong>Multi Steps Routes</strong> in the Inventory settings. See <a href="./../basic-setup/two-step-manufacturing.html">Two-step manufacturing</a>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>The settings only show or hide menus and tabs. Existing manufacturing orders and recipes stay as they are.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Manufacturing overview</a></li><li><a href="./first-steps.html">First steps</a></li><li><a href="./../advanced-configuration/work-centers.html">Work centers</a></li><li><a href="./../basic-setup/bill-of-materials.html">Bill of materials</a></li></ul>',15))])}const k=r(d,[["render",h]]);export{m as __pageData,k as default};
